head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.filterGubun = "";
scwin.questNo;
scwin.vCurDate;
scwin.vScrenID = "ULDSTF30322.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    trs_Read.Action = "/QuestionMgt.do?method=readQuestion&questNo=" + scwin.questNo + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyName = "toinb_dataid4";
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_Quest,O:pOutput2=dts_Ques,O:pOutput3=dts_Ques_Candidate_Val,O:pOutput4=dts_Ques_Coment)";
    trs_Read.Post();
};
scwin.fn_save = function() {
    //설문등록 
    //if(tbox_quest_title.value == "" || tbox_quest_title.value.indexOf(" ") == "" ){//설문제목 체크
    if (tbox_quest_title.getValue() == "") {
        //설문제목 체크
        $c.win.alert("[설문 제목]을 입력하세요");
        return;
    }
    if (!scwin.checkMaxLength1(tbox_quest_title, 1000, "설문 제목")) {
        tbox_quest_title.setValue("");
        tbox_quest_title.focus();
        return false;
    }
    if (edt_SDate.getValue() == "" || edt_SDate.Text.indexOf(" ") == "") {
        //설문시작일 체크
        $c.win.alert("[설문 시작일]을 선택하세요.");
        return;
    }
    if (edt_EDate.getValue() == "" || edt_EDate.Text.indexOf(" ") == "") {
        //설문종료일 체크
        $c.win.alert("[설문 종료일]을 선택하세요.");
        return;
    }
    if (scwin.dateCheck() == false) {
        return;
    }
    if (mkgubun.getValue() == "") {
        $c.win.alert("[설문대상 시장]을 선택하세요.");
        return;
    }
    if (dts_Ques.getTotalRow() == 0) {
        $c.win.alert("[질문]을 입력하세요");
        return;
    }
    if (scwin.Validate() == false) {
        return;
    }
    dts_Ques_Candidate_Val.UseFilter = true;
    scwin.filterGubun = "1";
    dts_Ques_Candidate_Val.Filter();
    dts_Ques_Coment.UseFilter = true;
    scwin.filterGubun = "1";
    dts_Ques_Coment.Filter();
    var index = 1;
    //질문후보값 SEQ 세팅
    var ques_no = dts_Ques_Candidate_Val.getCellData(1, "QUES_NO");
    for (i = 1; i <= dts_Ques_Candidate_Val.getTotalRow(); i++) {
        if (ques_no != dts_Ques_Candidate_Val.getCellData(i, "QUES_NO")) {
            ques_no = dts_Ques_Candidate_Val.getCellData(i, "QUES_NO");
            index = 1;
        }
        dts_Ques_Candidate_Val.setCellData(i, "QUES_CANDIDATE_VAL_SEQ", index);
        index++;
    }

    //주석문 SEQ 세팅
    index = 1;
    ques_no = dts_Ques_Coment.getCellData(1, "QUES_NO");
    for (i = 1; i <= dts_Ques_Coment.getTotalRow(); i++) {
        if (ques_no != dts_Ques_Coment.getCellData(i, "QUES_NO")) {
            ques_no = dts_Ques_Coment.getCellData(i, "QUES_NO");
            index = 1;
        }
        dts_Ques_Coment.setCellData(i, "QUES_COMENT_SEQ", index);
        index++;
    }

    //응답필수리스트 1자리숫자앞에 '0' 채워주기
    for (i = 1; i <= dts_Ques.getTotalRow(); i++) {
        if (dts_Ques.getCellData(i, "RESPNS_MANDTRY_NO") != "") {
            var mndt_nos = dts_Ques.getCellData(i, "RESPNS_MANDTRY_NO").split(',');
            var mndt_no = "";
            for (j = 0; j < mndt_nos.length; j++) {
                if (mndt_nos[j].length == 1) {
                    mndt_nos[j] = '0' + mndt_nos[j];
                }
                if (j > 0) {
                    mndt_nos[j] = ',' + mndt_nos[j];
                }
                mndt_no += mndt_nos[j];
            }
            dts_Ques.setCellData(i, "RESPNS_MANDTRY_NO", mndt_no);
        }
    }
    var rtn = confirm('내용을 등록 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        for (i = 1; i <= dts_Ques.getTotalRow(); i++) {
            if (dts_Ques.getCellData(i, "UP_QUES_NO") == "0" && dts_Ques.getCellData(i, "INDEX_GBN1") != "N") {
                dts_Ques.setCellData(i, "RESPNS_MANDTRY_YN", "Y");
            }
        }
        trs_Save.Action = "/QuestionMgt.do?method=registerQuestion&js_emp_no=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput1=dts_Quest,I:pInput2=dts_Ques,I:pInput3=dts_Ques_Candidate_Val,I:pInput4=dts_Ques_Coment)";
        trs_Save.Post();
    }
};
scwin.fn_update = function() {
    //if(tbox_quest_title.value == "" || tbox_quest_title.value.indexOf(" ") == "" ){//설문제목 체크
    if (tbox_quest_title.getValue() == "") {
        //설문제목 체크
        $c.win.alert("[설문 제목]을 입력하세요");
        return;
    }
    if (!scwin.checkMaxLength1(tbox_quest_title, 1000, "설문 제목")) {
        tbox_quest_title.setValue("");
        tbox_quest_title.focus();
        return false;
    }
    if (edt_SDate.getValue() == "" || edt_SDate.Text.indexOf(" ") == "") {
        //설문시작일 체크
        $c.win.alert("[설문 시작일]을 선택하세요.");
        return;
    }
    if (edt_EDate.getValue() == "" || edt_EDate.Text.indexOf(" ") == "") {
        //설문종료일 체크
        $c.win.alert("[설문 종료일]을 선택하세요.");
        return;
    }
    if (scwin.dateCheck() == false) {
        return;
    }
    if (mkgubun.getValue() == "") {
        $c.win.alert("[설문대상 시장]을 선택하세요.");
        return;
    }
    if (dts_Ques.getTotalRow() == 0) {
        $c.win.alert("[질문]을 입력하세요");
        return;
    }
    if (scwin.Validate() == false) {
        dts_Ques_Candidate_Val.UseFilter = true;
        scwin.filterGubun = "2";
        dts_Ques_Candidate_Val.Filter();
        return;
    }

    //응답필수리스트 1자리숫자앞에 '0' 채워주기
    for (i = 1; i <= dts_Ques.getTotalRow(); i++) {
        if (dts_Ques.getCellData(i, "RESPNS_MANDTRY_NO") != "") {
            var mndt_nos = dts_Ques.getCellData(i, "RESPNS_MANDTRY_NO").split(',');
            var mndt_no = "";
            for (j = 0; j < mndt_nos.length; j++) {
                if (mndt_nos[j].length == 1) {
                    mndt_nos[j] = '0' + mndt_nos[j];
                }
                if (j > 0) {
                    mndt_nos[j] = ',' + mndt_nos[j];
                }
                mndt_no += mndt_nos[j];
            }
            dts_Ques.setCellData(i, "RESPNS_MANDTRY_NO", mndt_no);
        }
    }
    var rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        for (i = 1; i <= dts_Ques.getTotalRow(); i++) {
            if (dts_Ques.getCellData(i, "UP_QUES_NO") == "0" && dts_Ques.getCellData(i, "INDEX_GBN1") != "N") {
                dts_Ques.setCellData(i, "RESPNS_MANDTRY_YN", "Y");
            }
        }
        trs_Update.Action = "/QuestionMgt.do?method=modifyQuestion&questNo=" + scwin.questNo + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Update.KeyValue = "JSP(I:pInput1=dts_Quest,I:pInput2=dts_Ques,I:pInput3=dts_Ques_Candidate_Val,I:pInput4=dts_Ques_Coment)";
        trs_Update.Post();
    }
};
scwin.fn_delete = function() {
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        //dts_Quest.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_Quest.insertRow();
        dts_Quest.setCellData(1, "QUEST_NO", scwin.questNo);
        trs_Delete.Action = "/QuestionMgt.do?method=removeQuestion&removeGubun=N" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput=dts_Quest)";
        trs_Delete.Post();
    }
};
scwin.fn_SetSaveHeader = function() {
    // CUD용 Header
    dts_Quest.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_QUEST_INOUT";
    dts_Quest.Reset();
    dts_Quest.insertRow();
    dts_Ques.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_QUES_INOUT";
    dts_Ques.Reset();
    dts_Ques_Candidate_Val.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_QUES_CANDIDATE_VAL_INOUT";
    dts_Ques_Candidate_Val.Reset();
    dts_Ques_Coment.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_QUES_COMENT_INOUT";
    dts_Ques_Coment.Reset();
};
scwin.setObjInit = function() {
    $c.stf.showObj(sub2_panel, false);
    chb_rsp_mndt_y.setDisabled(true);
    chb_rsp_mndt_n.setDisabled(true);
    ques_tp_cd.setDisabled(true);
    tbox_ans_choic_cnt.setReadOnly(true);
};
scwin.fn_initFilter = function() {
    dts_Ques_Candidate_Val.UseFilter = true;
    scwin.filterGubun = "2";
    dts_Ques_Candidate_Val.Filter();
    dts_Ques_Coment.UseFilter = true;
    dts_Ques_Coment.Filter();
};
scwin.fn_initload = function() {
    if (ques_tp_cd.getValue() != "2") {
        grd_ques_candidate_val.setDisabled(false);
        grd_ques_candidate_val.setDisabled(false);
    }

    //질문후보값, 주석값 필터링
    dts_Ques_Candidate_Val.UseFilter = true;
    scwin.filterGubun = "2";
    dts_Ques_Candidate_Val.Filter();
    dts_Ques_Coment.UseFilter = true;
    dts_Ques_Coment.Filter();
    tbox_ques_no.setValue(dts_Ques.getRowPosition());
    tbox_ans_choic_cnt.style.backgroundColor = "FFFFFF";
    scwin.mandtryYn();
    //선택개수입력 컨트롤

    if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_TP_CD") == "1" ||
        dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_TP_CD") == "4" ||
        dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_TP_CD") == "5") {
        tbox_ans_choic_cnt.setValue("");
        tbox_ans_choic_cnt.setReadOnly(true);
        tbox_ans_choic_cnt.style.backgroundColor = "b9d4f7";
    } else if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_TP_CD") == "") {
        tbox_ans_choic_cnt.setValue("");
        tbox_ans_choic_cnt.setReadOnly(true);
    } else {
        if (tbox_ans_choic_cnt.getValue() == "0") {
            tbox_ans_choic_cnt.setValue("");
        }
        tbox_ans_choic_cnt.setReadOnly(false);
        tbox_ans_choic_cnt.style.backgroundColor = "FFFFFF";
    }
};
scwin.mandtryYn = function() {
    //질문 필수선택 컨트롤
    if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN") == "Y") {
        if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "UP_QUES_NO") != "0") {
            $c.stf.showObj(sub2_panel, true);
            chb_rsp_mndt_y.setValue(1);
            chb_rsp_mndt_n.setValue(0);
            chb_rsp_mndt_y.setDisabled(false);
            chb_rsp_mndt_n.setDisabled(true);
        } else {
            $c.stf.showObj(sub2_panel, false);
            chb_rsp_mndt_y.setValue(0);
            chb_rsp_mndt_y.setDisabled(false);
            chb_rsp_mndt_n.setValue(0);
            chb_rsp_mndt_n.setDisabled(false);
        }
    } else if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN") == "N") {
        $c.stf.showObj(sub2_panel, false);
        chb_rsp_mndt_y.setValue(0);
        chb_rsp_mndt_y.setDisabled(true);
        chb_rsp_mndt_n.setValue(1);
        chb_rsp_mndt_n.setDisabled(false);
    } else {
        $c.stf.showObj(sub2_panel, false);
        chb_rsp_mndt_y.setValue(0);
        chb_rsp_mndt_y.setDisabled(false);
        chb_rsp_mndt_n.setValue(0);
        chb_rsp_mndt_n.setDisabled(false);
    }
};
scwin.isNumber = function(inputVal) {
    oneDecimal = false;
    var inputStr = inputVal.toString();
    var oneChar;
    for (var i = 0; i < inputStr.length; i++) {
        oneChar = inputStr.charAt(i);
        if (i == 0 && oneChar == "-") {
            continue;
        }
        if (oneChar == "." && !oneDecimal) {
            oneDecimal = true;
            continue;
        }
        if (oneChar < "0" || oneChar > "9") {
            return false;
        }
    }
    return true;
};
scwin.validCheck = function(obj) {
    //질문제목 체크
    if (dts_Ques.getCellData(obj, "QUES_CONTN") == "") {
        $c.win.alert("[" + obj + "번째 질문 제목]을 입력하세요");
        return false;
    }
    //질문 유형 체크
    if (dts_Ques.getCellData(obj, "QUES_TP_CD") == "") {
        $c.win.alert("[" + obj + "번째 질문 유형]을 입력하세요");
        return false;
    }
    //객관식 질문의 후보값 체크 -> 질문유형이 주관식이 아닐경우
    if (dts_Ques.getCellData(obj, "QUES_TP_CD") != "5") {
        if (scwin.questNo != "input") {
            dts_Ques_Candidate_Val.UseFilter = true;
            scwin.filterGubun = "1";
            dts_Ques_Candidate_Val.Filter();
            var checkVal = "";
            for (i = 1; i <= dts_Ques_Candidate_Val.getTotalRow(); i++) {
                if (dts_Ques.getCellData(obj, "QUES_NO") == dts_Ques_Candidate_Val.getCellData(i, "QUES_NO")) {
                    checkVal = "Y";
                }
            }
            if (checkVal != "Y") {
                dts_Ques_Candidate_Val.UseFilter = true;
                scwin.filterGubun = "2";
                dts_Ques_Candidate_Val.Filter();
                $c.win.alert("[" + obj + "번째 질문후보값]을 입력하세요");
                return false;
            }
        } else {
            if (dts_Ques_Candidate_Val.getTotalRow() < 1) {
                $c.win.alert("[" + obj + "번째 질문답변값]을 입력하세요");
                return false;
            } else {
                var ques_value_check = "";
                for (i = 1; i <= dts_Ques_Candidate_Val.getTotalRow(); i++) {
                    //질문후보값 체크
                    if (dts_Ques_Candidate_Val.getCellData(i, "QUES_CANDIDATE_VAL") == "") {
                        ques_value_check = ques_value_check + i + ",";
                    }
                }
                if (ques_value_check != "") {
                    $c.win.alert("[" + obj + "번째 질문]에 " + "[" + ques_value_check + "번째 답변값]을 입력하세요");
                    return false;
                }
            }
        }
    }
    if (dts_Ques.getCellData(obj, "QUES_TP_CD") == "2" || dts_Ques.getCellData(obj, "QUES_TP_CD") == "3") {
        if (dts_Ques.getCellData(obj, "ANS_CHOIC_CNT") == "" || dts_Ques.getCellData(obj, "ANS_CHOIC_CNT") == "0" || dts_Ques.getCellData(obj, "ANS_CHOIC_CNT").indexOf(" ") == "") {
            dts_Ques_Candidate_Val.UseFilter = true;
            scwin.filterGubun = "2";
            dts_Ques_Candidate_Val.Filter();
            $c.win.alert("[" + obj + "번째 질문의 선택갯수]를 입력해주세요.");
            return false;
        }
        if (!$c.cm.isNumber(dts_Ques.getCellData(obj, "ANS_CHOIC_CNT"))) {
            dts_Ques_Candidate_Val.UseFilter = true;
            scwin.filterGubun = "2";
            dts_Ques_Candidate_Val.Filter();
            $c.win.alert("[" + obj + "번째 질문의 선택갯수]를 숫자로 입력해주세요.");
            return false;
        }
        if (eval(dts_Ques.getCellData(obj, "ANS_CHOIC_CNT")) > dts_Ques_Candidate_Val.getTotalRow()) {
            dts_Ques_Candidate_Val.UseFilter = true;
            scwin.filterGubun = "2";
            dts_Ques_Candidate_Val.Filter();
            $c.win.alert("[" + obj + "번째 질문의 선택개수 또는 후보값 개수]가 바르지 않습니다.");
            return false;
        }
    }
    if (dts_Ques.getCellData(obj, "RESPNS_MANDTRY_YN") == "Y") {
        if (!$c.cm.isNumber(dts_Ques.getCellData(obj, "UP_QUES_NO"))) {
            dts_Ques_Candidate_Val.UseFilter = true;
            scwin.filterGubun = "2";
            dts_Ques_Candidate_Val.Filter();
            $c.win.alert("[" + obj + "번째 질문의 상위질문번호]를 숫자로 입력해주세요.");
            return false;
        }
        //상위질문번호가 있는지 검사.
        if (dts_Ques.getCellData(obj, "UP_QUES_NO") != "0") {
            var upQuesNoYn = "";
            for (i = 1; i <= dts_Ques.getTotalRow(); i++) {
                if (dts_Ques.getCellData(i, "QUES_NO") == dts_Ques.getCellData(obj, "UP_QUES_NO")) {
                    upQuesNoYn = "Y";
                }
            }
            if (upQuesNoYn != "Y") {
                dts_Ques_Candidate_Val.UseFilter = true;
                scwin.filterGubun = "2";
                dts_Ques_Candidate_Val.Filter();
                $c.win.alert("[" + obj + "번째 질문의 상위질문번호]가 없습니다.");
                return false;
            }
        }
    }
    for (i = 1; i <= obj - 1; i++) {
        if (dts_Ques.getCellData(i, "QUES_NO") == dts_Ques.getCellData(obj, "UP_QUES_NO")) {
            if (dts_Ques.getCellData(i, "QUES_TP_CD") != "5") {
                if (dts_Ques.getCellData(obj, "RESPNS_MANDTRY_NO") == "" ||
                    dts_Ques.getCellData(obj, "RESPNS_MANDTRY_NO") == "0" ||
                    dts_Ques.getCellData(obj, "RESPNS_MANDTRY_NO").indexOf(" ") == "") {
                    dts_Ques_Candidate_Val.UseFilter = true;
                    scwin.filterGubun = "2";
                    dts_Ques_Candidate_Val.Filter();
                    $c.win.alert("[" + obj + "번째 질문의 상위 질문에 대한 응답필수 답변번호]를 입력하세요.");
                    return false;
                }
            }
        }
    }
    if (scwin.questNo != "input") {
        dts_Ques_Candidate_Val.UseFilter = true;
        scwin.filterGubun = "2";
