scwin.btn_sub1_linedelete_onclick = function() {
    //질문내용 삭제

    var ques_no = dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO");
    var rsp_mndt_check = "";
    for (i = 1; i <= dts_Ques.getTotalRow(); i++) {
        if (ques_no == dts_Ques.getCellData(i, "UP_QUES_NO")) {
            rsp_mndt_check = "Y";
        }
    }
    if (rsp_mndt_check == "Y") {
        $c.win.alert("상위 질문번호가 존재하여 삭제하실수 없습니다. 질문필수 \n선택을 필수아님으로 선택하신 후 다시 시도 하십시오.");
        return;
    }

    //질문 후보값 삭제
    for (i = 1; i <= dts_Ques_Candidate_Val.getTotalRow(); i++) {
        if (dts_Ques_Candidate_Val.getCellData(eval(i), "QUES_NO") == ques_no) {
            $c.cp.removeRow(dts_Ques_Candidate_Val, i - 1);
        }
    }
    //주석값 삭제
    for (i = 1; i <= dts_Ques_Coment.getTotalRow(); i++) {
        if (dts_Ques_Coment.getCellData(eval(i), "QUES_NO") == ques_no) {
            $c.cp.removeRow(dts_Ques_Coment, i - 1);
        }
    }
    if (scwin.questNo != "input") {
        if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "INDEX_GBN") != "") {
            $c.cp.removeRow(dts_Ques, dts_Ques.getRowPosition());
            var rtn = confirm('행삭제를 하시면 실제 내용이 삭제 됩니다.\n내용을 삭제 하시겠습니까?');
            if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

            {
                //행삭제시 별도로 질문내용및 후보값과 주석문을 같이 삭제한다.
                trs_Delete2.Action = "/QuestionMgt.do?method=removeQuestion&removeGubun=Y";
                trs_Delete2.KeyValue = "JSP(I:pInput=dts_Ques)";
                trs_Delete2.Post();
            }
            //fn_initFilter();

        } else {
            $c.cp.removeRow(dts_Ques, dts_Ques.getRowPosition());
            quest_number.SetColumn("QUES_CONTN");
            quest_number.focus();
        }
    } else {
        $c.cp.removeRow(dts_Ques, dts_Ques.getRowPosition());
        quest_number.SetColumn("QUES_CONTN");
        quest_number.focus();
    }
    if (dts_Ques.getTotalRow() == 0) {
        scwin.setObjInit();
    }
    scwin.fn_initload();
};
