scwin.btn_sub2_linedelete1_onclick = function() {
    //질문후보값 삭제

    //응답필수번호 리스트 체크
    //질문번호
    var delQuesNo = dts_Ques_Candidate_Val.getCellData(dts_Ques_Candidate_Val.getRowPosition(), "QUES_NO");
    var delSeqNum = dts_Ques_Candidate_Val.getCellData(dts_Ques_Candidate_Val.getRowPosition(), "SEQ_NUM");

    //응답필수번호리스트
    var upQuesNoValYn = "";
    for (i = 1; i <= dts_Ques.getTotalRow(); i++) {
        if (dts_Ques.getCellData(i, "UP_QUES_NO") == delQuesNo) {
            var mndt_nos = dts_Ques.getCellData(i, "RESPNS_MANDTRY_NO").split(',');
            for (j = 0; j < mndt_nos.length; j++) {
                if (mndt_nos[j] == delSeqNum) {
                    upQuesNoValYn = "Y";
                }
            }
        }
    }
    if (upQuesNoValYn == "Y") {
        $c.win.alert("삭제 하려하시는 답변값을 응답필수 답변번호로 쓰고있는 질문이 있습니다.\n 확인 후 다시 시도해주세요.");
        return;
    }
    if (scwin.questNo != "input") {
        if (dts_Ques_Candidate_Val.getCellData(dts_Ques_Candidate_Val.getRowPosition(), "INDEX_GBN") != "") {
            $c.cp.removeRow(dts_Ques_Candidate_Val, dts_Ques_Candidate_Val.getRowPosition());
            var rtn = confirm('행삭제를 하시면 실제 내용이 삭제 됩니다.\n내용을 삭제 하시겠습니까?');
            if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

            {
                //행삭제시 별도로 질문내용및 후보값과 주석문을 같이 삭제한다.
                trs_Delete2.Action = "/QuestionMgt.do?method=removeQuestion&removeGubun=val";
                trs_Delete2.KeyValue = "JSP(I:pInput=dts_Ques_Candidate_Val)";
                trs_Delete2.Post();
                scwin.fn_initFilter();
            }
        } else {
            $c.cp.removeRow(dts_Ques_Candidate_Val, dts_Ques_Candidate_Val.getRowPosition());
            grd_ques_candidate_val.SetColumn("QUES_CANDIDATE_VAL");
            grd_ques_candidate_val.focus();
        }
    } else {
        $c.cp.removeRow(dts_Ques_Candidate_Val, dts_Ques_Candidate_Val.getRowPosition());
        grd_ques_candidate_val.SetColumn("QUES_CANDIDATE_VAL");
        grd_ques_candidate_val.focus();
    }
};
