scwin.dts_Ques_Candidate_Val_OnFilter = function(row) {
    //질문 후보값 그리드 내용 필터링 이벤트
    switch (scwin.filterGubun) {
        case "1":
            return true;
            break;
        case "2":
            var sub1 = dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO");
            var sub2_1 = dts_Ques_Candidate_Val.getCellData(row, "QUES_NO");
            if (sub1 == sub2_1) return true;

            else return false;
            return;
            break;
    }
};
scwin.dts_Ques_Coment_OnFilter = function(row) {
    //주석값 그리드 내용 필터링 이벤트
    switch (scwin.filterGubun) {
        case "1":
            return true;
            break;
        case "2":
            var sub1 = dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO");
            var sub2_1 = dts_Ques_Coment.getCellData(row, "QUES_NO");
            if (sub1 == sub2_1) {
                return true;
            } else return false;
            return;
            break;
    }
};
scwin.chb_rsp_mndt_y_onclick = function() {
    //종속필수 컨트롤
    if (dts_Ques.getTotalRow() != 0) {
        if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO") == "1") {
            dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN", "Y");
            dts_Ques.setCellData(dts_Ques.getRowPosition(), "INDEX_GBN1", "");
            $c.stf.showObj(sub2_panel, false);
            chb_rsp_mndt_y.setDisabled(true);
            chb_rsp_mndt_y.setValue(0);
            return;
        } else {
            dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN", "Y");
            if (chb_rsp_mndt_y.checked == true) {
                $c.stf.showObj(sub2_panel, true);
                chb_rsp_mndt_n.setDisabled("enable");
            } else {
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN", "Y");
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "INDEX_GBN1", "");
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "UP_QUES_NO", "0");
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_NO", "");
                $c.stf.showObj(sub2_panel, false);
                chb_rsp_mndt_n.setDisabled(false);
            }
        }
    }
};
scwin.chb_rsp_mndt_n_onclick = function() {
    //종속 필수 아님 컨트롤
    if (dts_Ques.getTotalRow() != 0) {
        /*	
        		if(dts_Ques.NameString(dts_Ques.RowPosition,"QUES_NO") == "1"){
        			chb_rsp_mndt_n.checked = true;
        			chb_rsp_mndt_y.checked = false;
        			return;
        		}
        */

        if (chb_rsp_mndt_n.checked == true) {
            dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN", "N");
            dts_Ques.setCellData(dts_Ques.getRowPosition(), "INDEX_GBN1", "N");
            tbox_up_ques_no.setValue("0");
            tbox_rsp_mndt_no.setValue("");
            chb_rsp_mndt_y.setDisabled("enable");
        } else {
            chb_rsp_mndt_y.setDisabled(false);
            dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN", "Y");
            dts_Ques.setCellData(dts_Ques.getRowPosition(), "INDEX_GBN1", "");
        }
    }
};
scwin.ques_tp_cd_OnSelChange = function() {
    //질문유형 이벤트
    if (ques_tp_cd.getValue() == "1" || ques_tp_cd.getValue() == "4" || ques_tp_cd.getValue() == "5") {
        tbox_ans_choic_cnt.setValue("");
        tbox_ans_choic_cnt.setReadOnly(true);
        tbox_ans_choic_cnt.style.backgroundColor = "b9d4f7"; //.background-color = "#b9d4f7";
        //질문 그리드 컨트롤 주관식으로 수정할경우
        if (ques_tp_cd.getValue() == "5") {
            var ques_no = dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO");
            for (i = 1; i <= dts_Ques_Candidate_Val.getTotalRow(); i++) {
                if (dts_Ques_Candidate_Val.getCellData(eval(i), "QUES_NO") == ques_no) {
                    $c.cp.removeRow(dts_Ques_Candidate_Val, i - 1);
                }
            }
            grd_ques_candidate_val.setDisabled(true);
            grd_ques_candidate_val.setDisabled(true);
        } else {
            grd_ques_candidate_val.setDisabled(false);
            grd_ques_candidate_val.setDisabled(false);
        }
    } else {
        tbox_ans_choic_cnt.setValue("");
        tbox_ans_choic_cnt.setReadOnly(false);
        grd_ques_candidate_val.setDisabled(false);
        tbox_ans_choic_cnt.style.backgroundColor = "FFFFFF";
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(main);
    $c.libRoundPanel.PanelToGroupBox(sub1);
    $c.cm.PanelToGroupBox(sub2);
    scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
    getQuestNo = $c.frame.path("../").fn_getQuestNo;
    scwin.questNo = getQuestNo();
    if (scwin.questNo != "input") {
        scwin.fn_read();
        //fn_mkGubunCheck();
        if (js_market == "1" || js_market == "2") {
            $c.stf.showObj(panel_mkt_gubun, false);
        } else {
            $c.stf.showObj(panel_mkt_gubun, true);
        }
        for (i = 1; i <= dts_Ques.getTotalRow(); i++) {
            if (dts_Ques.getCellData(i, "RESPNS_MANDTRY_YN") == "N") {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************

                /*ORG SRC: dts_Ques.nameString(i, "INDEX_GBN1") = "N";*/
                X = "N";
            }
        }
    } else {
        scwin.fn_SetSaveHeader();
        scwin.setObjInit();
        if (js_market == "1" || js_market == "2") {
            $c.stf.showObj(panel_mkt_gubun, false);
            dts_Quest.setCellData(1, "LD_MKT_TP_CD", js_market);
        } else {
            $c.stf.showObj(panel_mkt_gubun, true);
            mkgubun.setValue("1");
        }
        //fn_mkGubunCheck();

    }
};
